import json,glob,collections
recs=[]
for f in glob.glob('scratchpad/*/commands.jsonl'):
    for line in open(f):
        line=line.strip()
        if not line: continue
        try: r=json.loads(line); r['_f']=f.split('/')[1]; recs.append(r)
        except: pass
by=collections.Counter(r['_f'] for r in recs)
bybytes=collections.Counter()
for r in recs: bybytes[r['_f']]+= (r.get('bytes') or 0)
print(f"{'session folder':52s} {'cmds':>6s} {'MB out':>8s} {'avg KB':>7s}")
for f,n in by.most_common():
    print(f"{f:52s} {n:6d} {bybytes[f]/1e6:8.2f} {bybytes[f]/n/1000:7.1f}")
print()
big=sorted(recs,key=lambda r: -(r.get('bytes') or 0))[:10]
print("--- 10 largest single outputs ---")
for r in big: print(f"{(r.get('bytes') or 0)/1000:8.1f} KB  {r['command'][:95]!r}")
